<?php
defined('BASEPATH') or exit('No direct script access allowed');
class Company_project_billing_rates extends AdminController
{
 public function index()
 {
  if(!CompanyRequestScope::sealedFor($this)){show_error('Contexto indisponível.',503);return;}require_once APPPATH.'services/CompanyProjectBillingRates.php';require_once APPPATH.'services/CompanyProjects.php';$ctx=CompanyRequestScope::context();$issuer=$ctx->issuerId();$actor=$ctx->staffId();$acl=new IssuerResourceAccess($this->db,db_prefix());foreach([['projects','view'],['customers','view'],['invoices','view']] as [$f,$c])if(!$acl->can($issuer,$actor,$f,$c)){show_error('Sem permissão para consultar preços desta empresa.',403);return;}$this->output->set_header('Cache-Control: no-store');$csrf=$this->session->userdata('company_project_rates_csrf');if(!is_string($csrf)||!preg_match('/^[a-f0-9]{64}$/D',$csrf)){$csrf=bin2hex(random_bytes(32));$this->session->set_userdata('company_project_rates_csrf',$csrf);}$project=null;$current=null;$projects=[];$error=null;$currencies=[];$s=new CompanyProjectBillingRates($this->db,db_prefix());
  try{if($this->input->method(true)==='POST'){$token=$this->input->post('company_project_rates_csrf',false);if(!is_string($token)||!hash_equals($csrf,$token)){show_error('Recarregue antes de salvar.',403);return;}$input=$this->input->post('rate',false);$key=$this->input->post('request_key',false);$id=$this->input->post('project_id',false);if(!is_array($input)||!is_string($key)||$this->input->post('confirmed',false)!=='1')throw new DomainException('company_project_rate_invalid');$s->declareHourly($issuer,$actor,$id,$this->input->post('revision',false),$input,$key);CompanyRequestScope::invalidateCaches($this);redirect(CompanyRequestScope::adminUrl($this,'company_project_billing_rates?project='.(int)$id),'location',303);return;}elseif(!in_array($this->input->method(true),['GET','HEAD'],true)){show_error('Método não permitido.',405);return;}$id=$this->input->get('project',false);if($id!==null){$project=(new CompanyProjects($this->db,db_prefix()))->get($issuer,$actor,$id);$current=$s->current($issuer,$actor,$id);$currencies=(new CompanyInvoices($this->db,db_prefix()))->currencies($issuer,$actor);}else$projects=(new CompanyProjects($this->db,db_prefix()))->page($issuer,$actor)['items'];}
  catch(DomainException $e){if(in_array($e->getMessage(),['company_project_rate_denied','company_project_access_denied'],true)){show_error('Origem ou permissão indisponível.',403);return;}$this->output->set_status_header(in_array($e->getMessage(),['company_project_rate_stale','company_project_rate_conflict'],true)?409:422);$error='Confira revisão, moeda, taxa e arredondamento. Preços anteriores permanecem preservados.';}
  catch(Throwable $e){log_message('error','Company project rate unconfirmed; no values logged.');$this->output->set_status_header(503);$error='Não foi possível confirmar o preço. Recarregue antes de repetir.';}
  $this->load->view('admin/companies/project_billing_rates',['issuer'=>$issuer,'project'=>$project,'projects'=>$projects,'current'=>$current,'currencies'=>$currencies,'error'=>$error,'can_edit'=>$acl->can($issuer,$actor,'projects','edit')&&$acl->can($issuer,$actor,'invoices','create'),'company_project_rates_csrf'=>$csrf,'request_key'=>bin2hex(random_bytes(32))]);
 }
